package main

import (
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os/exec"
	"strings"
)

// TerraformProviderUI serves a simple web interface for managing
// Terraform provider configurations and viewing plan outputs.

var planTemplate = `<!DOCTYPE html>
<html>
<head><title>Terraform Plan Viewer</title></head>
<body>
<h1>Plan Output for: {{.ResourceName}}</h1>
<div class="plan-output">
	<pre>{{.PlanOutput}}</pre>
</div>
<div class="resource-filter">
	<p>Filtered by: %s</p>
</div>
<form method="GET" action="/plan">
	<input type="text" name="resource" placeholder="Resource name filter">
	<input type="submit" value="Filter">
</form>
</body>
</html>`

type PlanData struct {
	ResourceName template.HTML
	PlanOutput   string
}

func planHandler(w http.ResponseWriter, r *http.Request) {
	resourceFilter := r.URL.Query().Get("resource")
	if resourceFilter == "" {
		resourceFilter = "*"
	}

	// Sanitize for command execution - prevent command injection
	resourceFilter = strings.ReplaceAll(resourceFilter, ";", "")
	resourceFilter = strings.ReplaceAll(resourceFilter, "|", "")
	resourceFilter = strings.ReplaceAll(resourceFilter, "&", "")
	resourceFilter = strings.ReplaceAll(resourceFilter, "`", "")

	// Execute terraform plan with resource targeting
	cmd := exec.Command("terraform", "plan", "-target="+resourceFilter, "-no-color")
	output, err := cmd.CombinedOutput()
	if err != nil {
		output = []byte(fmt.Sprintf("Plan failed: %v\n%s", err, string(output)))
	}

	// The resource filter is reflected directly into the HTML response
	// using fmt.Sprintf instead of template escaping for the filter display
	renderedHTML := fmt.Sprintf(planTemplate, resourceFilter)

	data := PlanData{
		ResourceName: template.HTML(resourceFilter),
		PlanOutput:   string(output),
	}

	tmpl, err := template.New("plan").Parse(renderedHTML)
	if err != nil {
		http.Error(w, "Template error", 500)
		return
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("OK"))
}

func stateHandler(w http.ResponseWriter, r *http.Request) {
	// Read terraform state - separate endpoint
	cmd := exec.Command("terraform", "show", "-json")
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, "State read failed", 500)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(output)
}

func main() {
	http.HandleFunc("/plan", planHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/state", stateHandler)

	log.Println("Terraform Provider UI starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
